pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        address token = address(new MockToken());
        address from = address(0x1234);
        address to1 = address(0x5678);
        address to2 = address(0x9abc);
        uint amount = 100;

        MockToken(token).mint(from, amount);
        vm.prank(from);
        MockToken(token).approve(address(c), 1);

        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        uint[] memory vals = new uint[](2);
        vals[0] = amount;
        vals[1] = amount;

        bool ok;
        vm.prank(from);
        try c.transfer(from, token, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false, "Reference reverts on failed transferFrom");
    }
}

contract MockToken {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
